function migrateThreads(items,seed){return (items||[]).map((c,i)=>({...c,id:c.id||`${seed}-${i}`,owner:c.owner||npcForId(c.name)?.id||(c.name===state.profile.name?'you':'npc'),replies:migrateThreads(c.replies,`${seed}-${i}`)}))}
function migrateState(){state.posts=(state.posts||[]).map(p=>({...p,comments:migrateThreads(p.comments,p.id)}));state.boards=(state.boards||[]).map(b=>({...b,replies:migrateThreads(b.replies,b.id)}));state.storyReactions=state.storyReactions||[];state.worldStories=state.worldStories||[];if(state.started&&state.story){const seeds=state.posts.filter(p=>p.worldSeed&&String(p.id).startsWith(`seed-${state.story.id}-`));if(seeds.length<50){const existing=new Set(state.posts.map(p=>p.id));starterPosts(state.story).filter(p=>!existing.has(p.id)).slice(0,50-seeds.length).forEach(p=>state.posts.push(p))}}}
function openMediaDB(){if(!('indexedDB'in window))return Promise.reject(Error('Local media storage is unavailable in this browser.'));if(!mediaDbPromise)mediaDbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('famous-local-media',1);req.onupgradeneeded=()=>req.result.createObjectStore('uploads');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return mediaDbPromise}
function saveMedia(file){return openMediaDB().then(db=>new Promise((resolve,reject)=>{const id=uid(),tx=db.transaction('uploads','readwrite');tx.objectStore('uploads').put(file,id);tx.oncomplete=()=>resolve(id);tx.onerror=()=>reject(tx.error)}))}
function readMedia(id){return openMediaDB().then(db=>new Promise((resolve,reject)=>{const req=db.transaction('uploads','readonly').objectStore('uploads').get(id);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error)}))}
async function hydrateMedia(root=document){for(const img of root.querySelectorAll('img[src*="images.unsplash.com"]'))img.onerror=()=>{const frame=img.closest('.uploaded-media');if(frame&&!frame.querySelector('.media-missing'))frame.insertAdjacentHTML('beforeend','<small class="media-missing">Photo unavailable while offline.</small>')};for(const node of root.querySelectorAll('[data-media-id]')){if(node.src)continue;const id=node.dataset.mediaId;try{let url=mediaUrlCache.get(id);if(!url){const blob=await readMedia(id);if(!blob)continue;url=URL.createObjectURL(blob);mediaUrlCache.set(id,url)}node.src=url}catch{node.insertAdjacentHTML('afterend','<small class="media-missing">This upload is unavailable on this device.</small>')}}}
function loadAccounts(){try{const saved=JSON.parse(localStorage.getItem(ACCOUNTS_KEY)||'null');if(saved&&Array.isArray(saved.accounts)){const normalized=normalizeAccounts(saved,fresh());if(normalized.accounts.length){try{localStorage.setItem(ACCOUNTS_KEY,JSON.stringify(normalized))}catch{}return normalized}}}catch{}const initial={id:`local-${Date.now()}`,name:'Player 1',save:fresh()};localStorage.removeItem(KEY);const created={currentId:initial.id,accounts:[initial]};try{localStorage.setItem(ACCOUNTS_KEY,JSON.stringify(created))}catch{}return created}
function persistAccounts(){const ok=persistJSON(localStorage,ACCOUNTS_KEY,accounts);if(!ok&&!saveWarningShown){saveWarningShown=true;toast('Progress could not be saved on this device. Free storage space or export your save.')}if(ok)saveWarningShown=false;return ok}
