function setActiveAccount(id){currentAccountId=id;accounts.currentId=id;const account=accounts.accounts.find(x=>x.id===id);state={...fresh(),...(account?.save||fresh())};migrateState();page=state.started?'home':'stories';profileTab='posts';persistAccounts();render()}
function createLocalAccount(name){const clean=(name||'').trim().slice(0,28);if(!clean){toast('Add a name for this device profile.');return}const account={id:`local-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,name:clean,save:fresh()};accounts.accounts.push(account);persistAccounts();setActiveAccount(account.id);toast(`Welcome, ${clean}. Start a new story to begin.`)}
function fresh(){return {started:false,profile:{name:'You',handle:'@you',bio:'New here. Making something of it.',initial:'Y'},story:null,stats:{fame:0,aura:0,wealth:40,trust:0,stress:0},posts:[],messages:{},friends:[],enemies:[],completed:[],actions:{},unlocks:[],log:[],liked:[],saved:[],boards:[],reelVotes:{},chapter:1,day:1,notifications:[],worldStories:[],npcTasks:[],sound:false,createdAt:Date.now(),seenStory:false}}
