function esc(s=''){return escapeHTML(s)}
function storyList(){return storiesCatalog}
function themeMode(){try{return localStorage.getItem('famous-theme-mode-v1')||'system'}catch{return'system'}}
function applyTheme(mode=themeMode()){const next=mode==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):mode;document.documentElement.dataset.theme=next;document.documentElement.dataset.themeMode=mode;syncThemeControl()}
function syncThemeControl(){const dark=document.documentElement.dataset.theme==='dark',mode=themeMode(),button=document.querySelector('#theme-toggle'),meta=document.querySelector('#theme-color-meta');if(button){button.textContent=mode==='system'?'◐':dark?'☼':'☾';button.setAttribute('aria-label',`Appearance: ${mode}. Tap to change.`);button.title=`Appearance: ${mode[0].toUpperCase()+mode.slice(1)} (tap to change)`;button.setAttribute('aria-pressed',String(dark))}if(meta)meta.content=dark?'#0c0f13':'#f2f2f7'}
function setTheme(mode){try{localStorage.setItem('famous-theme-mode-v1',mode);localStorage.removeItem('famous-theme-v1')}catch{}applyTheme(mode)}
function toggleTheme(){const mode=themeMode(),next=mode==='system'?'light':mode==='light'?'dark':'system';setTheme(next);toast(next==='system'?'Following your iPhone appearance.':`${next==='dark'?'Dark':'Light'} appearance enabled.`)}
