function showHelp(){const root=document.querySelector('#modal-root');root.innerHTML=`<div class="compose-backdrop"><section class="dialog"><div class="modal-head"><div><div class="eyebrow">A QUICK FIELD GUIDE</div><h2>How to play.</h2></div><button class="close-button" data-close-modal>×</button></div><p style="font-size:14px;color:#626670">Choose an original story, make a character, and use the social feed to build a life in public. Posts, stories, reels, board notes, DMs, and chapter choices shift your stats and relationships.</p><div class="mission-row"><span class="mission-badge">✦</span><div><strong>Your choices have consequences.</strong><small>Fame can bring attention and pressure. Trust takes time. There are no perfect routes.</small></div></div><div class="mission-row"><span class="mission-badge">◉</span><div><strong>All characters are fictional.</strong><small>They react through a local rules engine. The game works without an AI API or internet connection.</small></div></div><div class="mission-row"><span class="mission-badge">▣</span><div><strong>Your save stays in this browser.</strong><small>Open You → Settings to export or restore a JSON save. Clearing browser storage removes it.</small></div></div><button class="button button-red" data-close-modal style="margin-top:12px">Got it</button></section></div>`;root.querySelectorAll('[data-close-modal]').forEach(b=>b.onclick=()=>root.innerHTML='')}
