function catchUpWorld(){if(!state.started)return;const last=Number(state.worldLastTick)||Date.now(),ticks=Math.min(8,Math.floor((Date.now()-last)/60000));for(let i=0;i<ticks;i++)worldActivityTick();if(!ticks)state.worldLastTick=last}
function boot(){bind();render();catchUpWorld();setInterval(()=>{if(state.started&&Date.now()-(Number(state.worldLastTick)||Date.now())>=60000)worldActivityTick()},15000);if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});if(state.started&&state.story)ensureStoryNPCs(Number(state.story.id))}
